package com.example.gameworkbench.service; import java.util.*; import org.springframework.stereotype.Service; import com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper; import com.example.gameworkbench.entity.*; import com.example.gameworkbench.mapper.*; import lombok.RequiredArgsConstructor;
@Service @RequiredArgsConstructor public class RetrievalRecordService { private final RetrievalRecordMapper records; private final AgentRunMapper runs; public List<RetrievalRecord> list(Long userId,Long projectId,Long agentRunId){AgentRun run=runs.selectOne(new LambdaQueryWrapper<AgentRun>().eq(AgentRun::getId,agentRunId).eq(AgentRun::getUserId,userId).eq(AgentRun::getProjectId,projectId));if(run==null)return List.of();return records.selectList(new LambdaQueryWrapper<RetrievalRecord>().eq(RetrievalRecord::getAgentRunId,agentRunId).eq(RetrievalRecord::getProjectId,projectId).orderByAsc(RetrievalRecord::getRankNo));} }
